async function viewerHash(token){return sha256Hex(`viewer:${clean(token)}`);}
function serverTeamBaseName(t){return t?.name||t?.team_name||t?.label||`Team ${t?.id??''}`;}
function serverRawSeasonText(t){const v=t?.season_name??t?.season_label??t?.season_title??t?.season;return v==null?'':String(v).trim();}
