async function prepareSourceGame(env,conn,session,gameRow,authCtx=null){const token=authCtx?.token||await traceGetToken(session.cookie_header),hash=authCtx?.hash,raw=(authCtx?.probeGame&&String(authCtx.probeGameId)===String(gameRow.game_id))?authCtx.probeGame:await traceRichGame(session.cookie_header,token,hash,gameRow.game_id),game=targetGameAsHome(raw,conn);if(game?.home_team&&statsNumber(game.home_team.score)===null&&statsNumber(gameRow?.team_score)!==null)game.home_team.score=statsNumber(gameRow.team_score);if(game?.away_team&&statsNumber(game.away_team.score)===null&&statsNumber(gameRow?.opponent_score)!==null)game.away_team.score=statsNumber(gameRow.opponent_score);if(!richGameUsable(game))throw new ApiError(`Trace game ${gameRow.game_id} returned insufficient detailed metadata.`,502,'trace_game_metadata_incomplete');const radars=await fetchRadars(session.cookie_header,game,conn.trace_slug);return saveTraceSource(env,conn.teamsnap_key,game,radars);}

async function claimHaloTask(env,key){const stale=new Date(Date.now()-5*60*1000).toISOString();await env.DB.prepare(`UPDATE trace_halo_tasks SET status='pending' WHERE teamsnap_key=? AND status='processing' AND updated_at<?`).bind(key,stale).run();const t=now();return env.DB.prepare(`UPDATE trace_halo_tasks SET status='processing',updated_at=? WHERE rowid=(SELECT rowid FROM trace_halo_tasks WHERE teamsnap_key=? AND status='pending' AND next_attempt_at<=? ORDER BY updated_at,game_id,half,member_gid LIMIT 1) RETURNING *`).bind(t,key,Date.now()).first();}
async function processHaloTask(env,key,cookie,task){const candidates=safeJsonParse(task.candidates_json,[]),idx=Math.max(0,Number(task.candidate_index||0)),candidate=clean(candidates[idx]),member=safeJsonParse(task.member_json,{}),clip=safeJsonParse(task.clip_json,{}),t=now();if(!candidate){await env.DB.prepare(`UPDATE trace_halo_tasks SET status='done',error='No Halo GID candidate',updated_at=? WHERE teamsnap_key=? AND game_id=? AND half=? AND member_gid=?`).bind(t,key,task.game_id,task.half,task.member_gid).run();return{done:true,tracking:false};}let segments=[];try{for(let chunk=0;chunk<HALO_CHUNKS;chunk++){const halo=await traceHaloRequest(cookie,traceHaloPayload(member,clip,candidate,chunk,'soccer')),part=TraceSourceTools.extractSegmentsFromRing(halo?.ring||[]);segments.push(...part);}segments=TraceSourceTools.mergeSegments(segments);if(segments.length){await env.DB.prepare(`UPDATE trace_halo_tasks SET status='done',attempts=attempts+1,segments_json=?,has_tracking=1,error=NULL,updated_at=? WHERE teamsnap_key=? AND game_id=? AND half=? AND member_gid=?`).bind(JSON.stringify(segments),t,key,task.game_id,task.half,task.member_gid).run();return{done:true,tracking:true};}if(idx+1<candidates.length){await env.DB.prepare(`UPDATE trace_halo_tasks SET status='pending',candidate_index=?,attempts=attempts+1,next_attempt_at=0,segments_json='[]',has_tracking=0,error=NULL,updated_at=? WHERE teamsnap_key=? AND game_id=? AND half=? AND member_gid=?`).bind(idx+1,t,key,task.game_id,task.half,task.member_gid).run();return{done:false,tracking:false};}await env.DB.prepare(`UPDATE trace_halo_tasks SET status='done',attempts=attempts+1,segments_json='[]',has_tracking=0,error=NULL,updated_at=? WHERE teamsnap_key=? AND game_id=? AND half=? AND member_gid=?`).bind(t,key,task.game_id,task.half,task.member_gid).run();return{done:true,tracking:false};}catch(e){if(e.code==='trace_auth_expired'||e.status===401){await env.DB.prepare(`UPDATE trace_halo_tasks SET status='pending',next_attempt_at=?,error=?,updated_at=? WHERE teamsnap_key=? AND game_id=? AND half=? AND member_gid=?`).bind(Date.now()+HALO_BLOCK_RETRY_MS,'Authentication expired',t,key,task.game_id,task.half,task.member_gid).run();throw e;}const attempts=Number(task.attempts||0)+1,blocked=e.code==='trace_halo_blocked'||e.status===403,limited=e.code==='trace_halo_rate_limited'||e.status===429,retryMs=blocked?HALO_BLOCK_RETRY_MS:limited?60*1000:HALO_ERROR_RETRY_MS,msg=clean(e.message||e).slice(0,500);if(attempts>=HALO_MAX_ATTEMPTS&&!blocked&&!limited){await env.DB.prepare(`UPDATE trace_halo_tasks SET status='done',attempts=?,next_attempt_at=0,segments_json='[]',has_tracking=0,error=?,updated_at=? WHERE teamsnap_key=? AND game_id=? AND half=? AND member_gid=?`).bind(attempts,`Collection ended after ${attempts} attempts: ${msg}`,t,key,task.game_id,task.half,task.member_gid).run();return{done:true,tracking:false,error:msg};}await env.DB.prepare(`UPDATE trace_halo_tasks SET status='pending',attempts=?,next_attempt_at=?,error=?,updated_at=? WHERE teamsnap_key=? AND game_id=? AND half=? AND member_gid=?`).bind(attempts,Date.now()+retryMs,msg,t,key,task.game_id,task.half,task.member_gid).run();return{done:false,tracking:false,error:msg,blocked,limited};}}
async function processHaloQueue(env,key,cookie,limit=HALO_TASKS_PER_TICK){let done=0,tracking=0,blocked=false;for(let i=0;i<limit;i++){const task=await claimHaloTask(env,key);if(!task)break;const r=await processHaloTask(env,key,cookie,task);done+=r.done?1:0;tracking+=r.tracking?1:0;if(r.blocked||r.limited){blocked=true;break;}}return{done,tracking,blocked};}
async function finalizeHaloGames(env,key){const rows=await env.DB.prepare(`SELECT s.game_id,s.season_key FROM trace_source_games s WHERE s.teamsnap_key=? AND s.source_status='halo' AND NOT EXISTS(SELECT 1 FROM trace_halo_tasks t WHERE t.teamsnap_key=s.teamsnap_key AND t.game_id=s.game_id AND t.status<>'done') ORDER BY s.updated_at LIMIT 4`).bind(key).all();let count=0;for(const row of rows.results||[]){const tasks=await env.DB.prepare(`SELECT half,member_gid,segments_json,error FROM trace_halo_tasks WHERE teamsnap_key=? AND game_id=? ORDER BY half,member_gid`).bind(key,row.game_id).all(),scans={1:{},2:{}},errors=[];for(const t of tasks.results||[]){const segs=safeJsonParse(t.segments_json,[]);if(segs.length)scans[Number(t.half)][String(t.member_gid)]=TraceSourceTools.mergeSegments(segs);if(clean(t.error))errors.push(`${t.member_gid}/H${t.half}: ${clean(t.error)}`);}const stamp=now();await env.DB.prepare(`UPDATE trace_source_games SET source_status='ready',engine_status='pending',scans_json=?,error=?,updated_at=? WHERE teamsnap_key=? AND game_id=?`).bind(JSON.stringify(scans),errors.length?errors.slice(0,8).join(' · '):null,stamp,key,row.game_id).run();await env.DB.prepare(`UPDATE trace_games SET playing_status='ready_for_engine',playing_error=NULL,playing_updated_at=?,playing_version=? WHERE teamsnap_key=? AND game_id=?`).bind(stamp,TRACE_ENGINE_VERSION,key,row.game_id).run();if(errors.length)await env.DB.prepare(`UPDATE trace_games SET playing_error=? WHERE teamsnap_key=? AND game_id=?`).bind('Some player tracking requests exhausted retries; best-effort calculation will continue.',key,row.game_id).run();await env.DB.prepare('DELETE FROM trace_halo_tasks WHERE teamsnap_key=? AND game_id=?').bind(key,row.game_id).run();count++;}return count;}

async function traceSeasonSourceTerminal(env,key,season){const catalog=await env.DB.prepare(`SELECT game_id,game_date FROM trace_games WHERE teamsnap_key=? AND (status IS NULL OR status='' OR LOWER(status)='ready')`).bind(key).all(),expected=(catalog.results||[]).filter(r=>traceSeasonKey(r.game_date)===season).map(r=>String(r.game_id));if(!expected.length)return true;const src=await env.DB.prepare('SELECT game_id,source_status FROM trace_source_games WHERE teamsnap_key=? AND season_key=?').bind(key,season).all(),statuses=new Map((src.results||[]).map(r=>[String(r.game_id),clean(r.source_status)]));return expected.every(id=>['ready','error'].includes(statuses.get(id)));}
async function traceEngineWork(env,publicKey,owner){await requireExistingDataset(env,publicKey);const key=await tenantKeyFor(env,owner,publicKey),conn=await ownedConnection(env,key,owner);if(!conn)throw new ApiError('Trace is not connected for this team.',404,'trace_not_connected');const stale=new Date(Date.now()-10*60*1000).toISOString();await env.DB.prepare(`UPDATE trace_source_games SET engine_status='stale' WHERE teamsnap_key=? AND engine_status='processing' AND updated_at<?`).bind(key,stale).run();const candidates=await env.DB.prepare(`SELECT * FROM trace_source_games WHERE teamsnap_key=? AND source_status='ready' AND engine_status IN ('stale','pending') ORDER BY updated_at DESC,CAST(game_id AS INTEGER) DESC LIMIT 30`).bind(key).all();let target=null;for(const candidate of candidates.results||[]){target=await env.DB.prepare(`UPDATE trace_source_games SET engine_status='processing',updated_at=? WHERE teamsnap_key=? AND game_id=? AND source_status='ready' AND engine_status IN ('stale','pending') RETURNING *`).bind(now(),key,candidate.game_id).first();if(target)break;}if(!target)return json({ok:true,work:null,status:await unifiedStatus(env,publicKey,conn,owner)});const seasonRows=await env.DB.prepare(`SELECT game_id,identity_json,base_result_json,event_json FROM trace_source_games WHERE teamsnap_key=? AND season_key=? AND source_status='ready'`).bind(key,target.season_key).all(),ds=await unifiedDataset(env,publicKey),publishedMap=new Map();if(ds){const rows=await env.DB.prepare(`SELECT data_json FROM trace_match_payloads WHERE family_key=? AND generation_id=?`).bind(publicKey,ds.active_generation).all();for(const r of rows.results||[]){const m=safeJsonParse(r.data_json,null);if(m&&clean(m.season_key)===clean(target.season_key))publishedMap.set(String(m.trace_game_id),m);}}for(const r of seasonRows.results||[]){const stage=safeJsonParse(r.event_json,null)?.match_template;if(stage)publishedMap.set(String(stage.trace_game_id),stage);}return json({ok:true,work:{engine_version:TRACE_ENGINE_VERSION,source_version:TRACE_SOURCE_VERSION,game_id:target.game_id,season_key:target.season_key,target:{metadata:safeJsonParse(target.metadata_json,{}),summary:safeJsonParse(target.summary_json,{}),scans:safeJsonParse(target.scans_json,{})},identities:Object.fromEntries((seasonRows.results||[]).map(r=>[String(r.game_id),safeJsonParse(r.identity_json,{})])),base_results:(seasonRows.results||[]).map(r=>safeJsonParse(r.base_result_json,null)).filter(Boolean),published_matches:[...publishedMap.values()],team:{trace_team_id:safeJsonParse(conn.meta_json,{}).trace_team_id??null,trace_team_slug:conn.trace_slug,name:conn.trace_team_name||conn.teamsnap_team_name||''}},status:await unifiedStatus(env,publicKey,conn,owner)});}
function validateEngineCommitMatch(m,season){if(!m||!clean(m.trace_game_id)||!Array.isArray(m.players))throw new ApiError('Trace engine returned an invalid match.',400,'trace_engine_match_invalid');if(clean(m.season_key)!==clean(season))throw new ApiError('Trace engine returned a match from the wrong season.',409,'trace_engine_season_mismatch');if(m.players.length>120)throw new ApiError('Trace engine returned too many player rows.',400,'trace_engine_match_invalid');return m;}
async function traceEngineCommit(request,env,owner){
  const b=await bodyJson(request),publicKey=clean(b.family_key),gameId=clean(b.game_id);
  if(!keyOk(publicKey)||!gameId)throw new ApiError('Trace engine commit is missing team or game identity.',400,'trace_engine_commit_invalid');
  if(clean(b.engine_version)!==TRACE_ENGINE_VERSION)throw new ApiError('This browser is using an older Trace engine. Refresh myTS and try again.',409,'trace_engine_version_mismatch');
  await requireExistingDataset(env,publicKey);
  const key=await tenantKeyFor(env,owner,publicKey),conn=await ownedConnection(env,key,owner);
  if(!conn)throw new ApiError('Trace is not connected for this team.',404,'trace_not_connected');
  const source=await env.DB.prepare('SELECT * FROM trace_source_games WHERE teamsnap_key=? AND game_id=?').bind(key,gameId).first();
  if(!source||source.source_status!=='ready')throw new ApiError('That Trace game is not ready for calculation.',409,'trace_engine_source_not_ready');
  const base=b.base_result;
  if(!base||String(base.game_id)!==String(gameId)||!Array.isArray(base.players))throw new ApiError('Trace engine base result is invalid.',400,'trace_engine_base_invalid');
  const others=await env.DB.prepare(`SELECT COUNT(*) AS n FROM trace_source_games WHERE teamsnap_key=? AND season_key=? AND source_status='ready' AND game_id<>? AND engine_status IN ('stale','pending','processing')`).bind(key,source.season_key,gameId).first();
  const remaining=Number(others?.n||0),stamp=now();
  let published=false,committed=0;
  if(remaining===0&&await traceSeasonSourceTerminal(env,key,source.season_key)){
    const matches=(Array.isArray(b.matches)?b.matches:[]).map(m=>validateEngineCommitMatch(m,source.season_key));
    if(!matches.length)throw new ApiError('Trace engine did not return the completed season matches.',400,'trace_engine_matches_missing');
    const validIds=new Set((await env.DB.prepare('SELECT game_id FROM trace_source_games WHERE teamsnap_key=? AND season_key=? AND source_status=?').bind(key,source.season_key,'ready').all()).results?.map(r=>String(r.game_id))||[]),matchIds=new Set(matches.map(m=>String(m.trace_game_id)));
    for(const m of matches)if(!validIds.has(String(m.trace_game_id)))throw new ApiError(`Trace engine returned unknown game ${m.trace_game_id}.`,409,'trace_engine_game_mismatch');
    if(matchIds.size!==validIds.size||[...validIds].some(id=>!matchIds.has(id)))throw new ApiError('Trace engine did not return every completed game in this season. Nothing was published.',409,'trace_engine_season_incomplete');
    await saveUnifiedMatches(env,conn,matches);
    published=true;committed=matches.length;
  }
  await env.DB.prepare(`UPDATE trace_source_games SET base_result_json=?,event_json=?,engine_version=?,engine_status='complete',error=NULL,updated_at=? WHERE teamsnap_key=? AND game_id=? AND source_status='ready'`).bind(JSON.stringify(base),JSON.stringify(b.event_payload||{}),TRACE_ENGINE_VERSION,stamp,key,gameId).run();
  await env.DB.prepare(`UPDATE trace_games SET playing_status='ready',playing_error=NULL,playing_updated_at=?,playing_version=? WHERE teamsnap_key=? AND game_id=?`).bind(stamp,TRACE_ENGINE_VERSION,key,gameId).run();
  const prog=await traceProgress(env,key),meta=safeJsonParse(conn.meta_json,{});
  meta.last_engine_commit={at:stamp,game_id:gameId,season_key:source.season_key,engine_version:TRACE_ENGINE_VERSION,published,remaining_season_games:remaining};
  const syncStatus=prog.done?(prog.errors?'synced_partial':'synced'):'syncing';
  await env.DB.prepare('UPDATE trace_connections SET meta_json=?,last_sync_at=?,updated_at=?,sync_status=? WHERE teamsnap_key=?').bind(JSON.stringify(meta),prog.done?stamp:conn.last_sync_at,stamp,syncStatus,key).run();
  return json({ok:true,game_id:gameId,season_key:source.season_key,published,committed_matches:committed,remaining_season_games:remaining,status:await unifiedStatus(env,publicKey,await connection(env,key),owner)});
}


async function processTraceEngineQueue(env,key,owner,limit=1){
  const conn=await ownedConnection(env,key,owner);if(!conn)return{processed:0,published:0};
  const publicKey=publicKeyForConnection(conn);let processed=0,published=0,lastError=null;
  for(let i=0;i<Math.max(0,Math.min(2,Number(limit)||1));i++){
    const workResponse=await traceEngineWork(env,publicKey,owner),packet=await workResponse.json();
    if(!packet?.work)break;
    const gameId=String(packet.work.game_id);
    try{
      const built=traceEnginePrepareWork(packet.work),request=new Request('https://myts.internal/api/admin/trace/engine/commit',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({family_key:publicKey,game_id:gameId,engine_version:TraceEngine.ENGINE_VERSION,base_result:built.base,event_payload:built.event_payload,matches:built.matches})}),commit=await traceEngineCommit(request,env,owner),result=await commit.json();
      processed++;if(result?.published)published++;
    }catch(e){lastError=e;const stamp=now(),msg=clean(e?.message||e).slice(0,500);await env.DB.prepare(`UPDATE trace_source_games SET engine_status='stale',error=?,updated_at=? WHERE teamsnap_key=? AND game_id=? AND source_status='ready'`).bind(msg,stamp,key,gameId).run().catch(()=>{});await env.DB.prepare(`UPDATE trace_games SET playing_status='ready_for_engine',playing_error=?,playing_updated_at=?,playing_version=? WHERE teamsnap_key=? AND game_id=?`).bind(msg,stamp,TRACE_ENGINE_VERSION,key,gameId).run().catch(()=>{});break;}
  }
  return{processed,published,last_error:lastError?clean(lastError.message||lastError):null};
}

async function traceEngineRelease(request,env,owner){const b=await bodyJson(request),publicKey=clean(b.family_key),gameId=clean(b.game_id);if(!keyOk(publicKey)||!gameId)throw new ApiError('Trace engine release is missing team or game identity.',400,'trace_engine_release_invalid');await requireExistingDataset(env,publicKey);const key=await tenantKeyFor(env,owner,publicKey),conn=await ownedConnection(env,key,owner);if(!conn)throw new ApiError('Trace is not connected for this team.',404,'trace_not_connected');const msg=clean(b.error||'Calculation was interrupted.').slice(0,500),stamp=now();await env.DB.prepare(`UPDATE trace_source_games SET engine_status='stale',error=?,updated_at=? WHERE teamsnap_key=? AND game_id=? AND source_status='ready'`).bind(msg,stamp,key,gameId).run();await env.DB.prepare(`UPDATE trace_games SET playing_status='ready_for_engine',playing_error=?,playing_updated_at=?,playing_version=? WHERE teamsnap_key=? AND game_id=?`).bind(msg,stamp,TRACE_ENGINE_VERSION,key,gameId).run();return json({ok:true,status:await unifiedStatus(env,publicKey,await connection(env,key),owner)});}

async function queueEngineRefresh(env,conn){if(!conn)return conn;const meta=safeJsonParse(conn.meta_json,{});if(meta.engine_refresh_version===TRACE_ENGINE_VERSION)return conn;const t=now();await env.DB.prepare(`UPDATE trace_source_games SET engine_status='stale',updated_at=? WHERE teamsnap_key=? AND source_status='ready' AND (engine_version IS NULL OR engine_version<>?)`).bind(t,conn.teamsnap_key,TRACE_ENGINE_VERSION).run();await env.DB.prepare(`UPDATE trace_games SET playing_status='ready_for_engine',playing_error=NULL,playing_updated_at=? WHERE teamsnap_key=? AND game_id IN (SELECT game_id FROM trace_source_games WHERE teamsnap_key=? AND source_status='ready' AND engine_status='stale')`).bind(t,conn.teamsnap_key,conn.teamsnap_key).run();meta.engine_refresh_version=TRACE_ENGINE_VERSION;meta.engine_refresh_at=t;await env.DB.prepare('UPDATE trace_connections SET meta_json=?,updated_at=? WHERE teamsnap_key=?').bind(JSON.stringify(meta),t,conn.teamsnap_key).run();return connection(env,conn.teamsnap_key);}
async function markAuthExpired(env,key){await env.DB.prepare('UPDATE trace_connections SET sync_status=?,updated_at=? WHERE teamsnap_key=?').bind('auth_expired',now(),key).run();}
async function syncTeam(env,key,{owner=null,gameLimit=1,refreshCatalog=true,retryErrors=false}={}){let conn=owner?await ownedConnection(env,key,owner):await connection(env,key);if(!conn||!clean(conn.owner_hash))return{ok:false,error:'Trace is not connected for this team.',http_status:404};owner=owner||conn.owner_hash;const session=await authSession(env,owner);if(!session){await markAuthExpired(env,key);return{ok:false,error:'Trace sign-in has expired. Reconnect Trace; saved stats are still available.',code:'trace_auth_expired',http_status:401,status:await statusFor(env,await connection(env,key),owner)};}try{const meta=safeJsonParse(conn.meta_json,{}),catalogAge=Date.now()-Date.parse(meta.catalog_updated_at||'');if(refreshCatalog&&(!Number.isFinite(catalogAge)||catalogAge>CATALOG_REFRESH_MS)){await refreshTraceCatalog(env,conn,session.cookie_header);conn=await connection(env,key);await env.DB.prepare('UPDATE trace_auth_sessions SET last_verified_at=?,updated_at=? WHERE owner_hash=?').bind(now(),now(),owner).run();}}catch(e){if(e.code==='trace_auth_expired'||e.status===401){await markAuthExpired(env,key);return{ok:false,error:'Trace sign-in has expired. Reconnect Trace; saved stats are still available.',code:'trace_auth_expired',http_status:401,status:await statusFor(env,await connection(env,key),owner)};}return{ok:false,error:e.message||'Trace roster could not be refreshed.',code:e.code||'catalog_refresh_failed',http_status:e.status||502,status:await statusFor(env,await connection(env,key),owner)};}conn=await queueEngineRefresh(env,await connection(env,key));if(retryErrors){await env.DB.prepare(`UPDATE trace_source_games SET source_status='error',updated_at=? WHERE teamsnap_key=? AND source_status='error'`).bind(new Date(0).toISOString(),key).run();await env.DB.prepare(`UPDATE trace_halo_tasks SET status='pending',next_attempt_at=0,error=NULL WHERE teamsnap_key=? AND status<>'done'`).bind(key).run();}
  let authCtx=null,lastError=null,prepared=0;const maxPrep=Math.max(0,Math.min(1,Number(gameLimit)||1));for(let i=0;i<maxPrep;i++){const g=await claimNextSourceGame(env,key);if(!g)break;try{if(!authCtx){const token=await traceGetToken(session.cookie_header),access=await traceAccessProfile(env,conn,session.cookie_header,token,session.trace_user_id,g.game_id);authCtx={token,hash:access.hash,probeGame:access.probeGame,probeGameId:g.game_id};}await prepareSourceGame(env,conn,session,g,authCtx);prepared++;}catch(e){lastError=e;if(e.code==='trace_auth_expired'||e.status===401){await env.DB.prepare(`UPDATE trace_games SET playing_status=NULL,playing_error=NULL WHERE teamsnap_key=? AND game_id=?`).bind(key,g.game_id).run();await markAuthExpired(env,key);return{ok:false,error:'Trace sign-in has expired. Reconnect Trace; saved stats are still available.',code:'trace_auth_expired',http_status:401,status:await statusFor(env,await connection(env,key),owner)};}const stamp=now(),msg=clean(e.message||e).slice(0,700);await env.DB.prepare(`INSERT INTO trace_source_games(teamsnap_key,game_id,season_key,source_status,engine_status,source_version,error,created_at,updated_at) VALUES(?,?,?,'error','pending',?,?,?,?) ON CONFLICT(teamsnap_key,game_id) DO UPDATE SET source_status='error',error=excluded.error,updated_at=excluded.updated_at`).bind(key,String(g.game_id),traceSeasonKey(g.game_date),TRACE_SOURCE_VERSION,msg,stamp,stamp).run();await env.DB.prepare(`UPDATE trace_games SET playing_status='source_error',playing_error=?,playing_updated_at=?,playing_version=? WHERE teamsnap_key=? AND game_id=?`).bind(msg,stamp,TRACE_ENGINE_VERSION,key,g.game_id).run();}}
  try{const halo=await processHaloQueue(env,key,session.cookie_header,HALO_TASKS_PER_TICK);if(halo.blocked)lastError=new Error('Trace temporarily limited tracking requests; collection will resume automatically.');}catch(e){lastError=e;if(e.code==='trace_auth_expired'||e.status===401){await markAuthExpired(env,key);return{ok:false,error:'Trace sign-in has expired. Reconnect Trace; saved stats are still available.',code:'trace_auth_expired',http_status:401,status:await statusFor(env,await connection(env,key),owner)};}}
  const ready=await finalizeHaloGames(env,key),engineRun=await processTraceEngineQueue(env,key,owner,1);conn=await connection(env,key);const prog=await traceProgress(env,key),meta=safeJsonParse(conn.meta_json,{}),stamp=now();meta.last_source_progress={at:stamp,prepared,halo_ready:ready,engine_processed:engineRun.processed,engine_published:engineRun.published,processed:prog.processed,total:prog.total,engine_ready:prog.engine_ready,collecting:prog.collecting,errors:prog.errors,engine_version:TRACE_ENGINE_VERSION,source_version:TRACE_SOURCE_VERSION};const syncStatus=clean(conn.sync_status)==='auth_expired'?'auth_expired':prog.done?(prog.errors?'synced_partial':'synced'):'syncing';await recountUnifiedDataset(env,publicKeyForConnection(conn),conn);await env.DB.prepare('UPDATE trace_connections SET meta_json=?,last_sync_at=?,updated_at=?,sync_status=? WHERE teamsnap_key=?').bind(JSON.stringify(meta),prog.done?stamp:conn.last_sync_at,stamp,syncStatus,key).run();return{ok:true,prepared,ready_for_engine:ready,processed_games:prog.processed,total_games:prog.total,successful_games:prog.successful,error_games:prog.errors,engine_ready_games:prog.engine_ready,done:prog.done,last_error:lastError?clean(lastError.message||lastError):null,status:await statusFor(env,await connection(env,key),owner)};}

function startTraceBackground(ctx,env,key,owner,{refreshCatalog=false,retryErrors=false,gameLimit=BACKGROUND_INITIAL_GAMES}={}){if(!ctx?.waitUntil||!keyOk(key)||!owner)return;ctx.waitUntil(syncTeam(env,key,{owner,gameLimit,refreshCatalog,retryErrors}).catch(e=>console.error('Trace background sync failed',key,e)));}
async function maybeContinueTrace(env,ctx,key,owner){if(!ctx?.waitUntil||!keyOk(key)||!owner)return;const conn=await ownedConnection(env,key,owner);if(!conn||clean(conn.sync_status)==='auth_expired')return;const prog=await traceProgress(env,key);if(prog.pending>0||prog.collecting>0){startTraceBackground(ctx,env,key,owner,{refreshCatalog:false,gameLimit:BACKGROUND_INITIAL_GAMES});return;}const meta=safeJsonParse(conn.meta_json,{}),age=Date.now()-Date.parse(meta.catalog_updated_at||conn.last_sync_at||0);if(!Number.isFinite(age)||age>=CATALOG_REFRESH_MS)startTraceBackground(ctx,env,key,owner,{refreshCatalog:true,gameLimit:BACKGROUND_INITIAL_GAMES});}
async function disconnectTrace(env,key,owner){const conn=await ownedConnection(env,key,owner);if(!conn)return;await env.DB.batch([env.DB.prepare('DELETE FROM trace_halo_tasks WHERE teamsnap_key=?').bind(key),env.DB.prepare('DELETE FROM trace_source_games WHERE teamsnap_key=?').bind(key),env.DB.prepare('DELETE FROM trace_games WHERE teamsnap_key=?').bind(key),env.DB.prepare('DELETE FROM trace_players WHERE teamsnap_key=?').bind(key),env.DB.prepare('DELETE FROM trace_connections WHERE teamsnap_key=? AND owner_hash=?').bind(key,owner)]);const remain=await env.DB.prepare('SELECT COUNT(*) AS n FROM trace_connections WHERE owner_hash=?').bind(owner).first();if(!Number(remain?.n||0)){const session=await authSession(env,owner);if(session?.cookie_header){try{const fd=new FormData();await traceFetch(`${TRACE_TEAMS}/users/self/logout`,{method:'POST',cookie:session.cookie_header,body:fd});}catch{}}await env.DB.batch([env.DB.prepare('DELETE FROM trace_auth_sessions WHERE owner_hash=?').bind(owner),env.DB.prepare('DELETE FROM trace_auth_pending WHERE owner_hash=?').bind(owner)]);}}
async function handleApi(request,env,ctx=null){
  await ensureSchema(env);const url=new URL(request.url),path=url.pathname;
  if(path==='/api/health')return json({ok:true,service:'myTS',version:APP_VERSION});
  if(path==='/api/public/state'&&request.method==='GET'){const cfg=await appConfig(env),teams=await env.DB.prepare('SELECT COUNT(*) AS n FROM app_teams').first();return json({configured:!!cfg?.teamsnap_token_enc&&Number(teams?.n||0)>0,private_view:true,version:APP_VERSION});}
  if(path==='/api/admin/status'&&request.method==='GET'){await requireAdmin(request,env);return adminStatus(request,env);}
  if(path==='/api/admin/teamsnap/connect'&&request.method==='POST')return connectTeamSnap(request,env);
  if(path==='/api/admin/sync'&&request.method==='POST'){await requireAdmin(request,env);return json(await syncTeamSnap(env));}
  if(path==='/api/admin/settings'&&request.method==='PUT'){await requireAdmin(request,env);return saveAppSettings(request,env);}
  if(path==='/api/admin/viewer-link/rotate'&&request.method==='POST'){await requireAdmin(request,env);return rotateViewerLink(request,env);}
  if(path==='/api/public/bootstrap'&&request.method==='GET'){const access=await requireViewer(request,env),response=await publicBootstrap(env,access);await maybeSyncTeamSnap(env,ctx);return response;}
  if(path==='/api/public/team'&&request.method==='GET'){const access=await requireViewer(request,env);return publicTeam(env,url.searchParams.get('team_id'),access);}
  const owner=await installationOwner(env);
  if(path==='/api/trace/status'&&request.method==='GET'){const access=await requireViewer(request,env),publicKey=clean(url.searchParams.get('key'));if(!keyOk(publicKey))throw new ApiError('Missing team key.',400);requireDatasetFamily(access,publicKey);const key=await tenantKeyFor(env,owner,publicKey),conn=await connection(env,key);if(access.admin&&conn)await maybeContinueTrace(env,ctx,key,owner);return json({ok:true,status:await unifiedStatus(env,publicKey,conn,access.admin?owner:null),auth:{session_present:access.admin?!!(await authSession(env,owner)):false}});}
  if(path==='/api/trace/map'&&request.method==='GET'){const access=await requireViewer(request,env),publicKey=clean(url.searchParams.get('key'));requireDatasetFamily(access,publicKey);return traceMapGet(env,publicKey);}
  if(path==='/api/trace/data'&&request.method==='GET'){const access=await requireViewer(request,env),publicKey=clean(url.searchParams.get('key'));if(!keyOk(publicKey))throw new ApiError('Missing team key.',400);requireDatasetFamily(access,publicKey);const key=await tenantKeyFor(env,owner,publicKey),conn=await connection(env,key);return unifiedData(env,publicKey,conn,access.admin?owner:null);}
  await requireAdmin(request,env);
  if(path==='/api/admin/trace/engine/work'&&request.method==='GET'){const publicKey=clean(url.searchParams.get('key'));if(!keyOk(publicKey))throw new ApiError('Missing team key.',400);return traceEngineWork(env,publicKey,owner);}
  if(path==='/api/admin/trace/engine/commit'&&request.method==='POST')return traceEngineCommit(request,env,owner);
  if(path==='/api/admin/trace/engine/release'&&request.method==='POST')return traceEngineRelease(request,env,owner);
  if(path==='/api/admin/trace/dataset/export'&&request.method==='GET'){const publicKey=clean(url.searchParams.get('key'));await requireExistingDataset(env,publicKey);return json({ok:true,snapshot:await buildUnifiedSnapshot(env,publicKey)});}
  if(path==='/api/admin/trace/dataset/import'&&request.method==='POST')return importUnifiedSnapshot(request,env,owner);
  if(path==='/api/trace/map'&&request.method==='PUT')return traceMapSave(request,env);
  if(path==='/api/trace/diagnostics'&&request.method==='GET'){const publicKey=clean(url.searchParams.get('key'));if(!keyOk(publicKey))throw new ApiError('Missing team key.',400);await requireExistingDataset(env,publicKey);const key=await tenantKeyFor(env,owner,publicKey),z=await traceDiagnosticsFor(env,key,owner);return json(z,z.ok?200:404);}
  if(path==='/api/trace/auth/send-code'&&request.method==='POST')return sendTraceCode(request,env,owner);
  if(path==='/api/trace/auth/verify-code'&&request.method==='POST')return verifyTraceCode(request,env,owner,ctx);
  if(path==='/api/trace/auth/connect-existing'&&request.method==='POST')return connectWithExistingSession(request,env,owner,ctx);
  if(path==='/api/trace/auth/select-team'&&request.method==='POST')return selectAuthenticatedTeam(request,env,owner,ctx);
  if(path==='/api/trace/connect'&&request.method==='DELETE'){const publicKey=clean(url.searchParams.get('key'));if(!keyOk(publicKey))throw new ApiError('Missing team key.',400);await requireExistingDataset(env,publicKey);const key=await tenantKeyFor(env,owner,publicKey);await disconnectTrace(env,key,owner);return json({ok:true,status:await unifiedStatus(env,publicKey,null,null)});}
  if(path==='/api/trace/sync'&&request.method==='POST'){const b=await bodyJson(request),publicKey=clean(b.teamsnap_key||url.searchParams.get('key'));if(!keyOk(publicKey))throw new ApiError('Missing team key.',400);await requireExistingDataset(env,publicKey);const key=await tenantKeyFor(env,owner,publicKey),conn=await ownedConnection(env,key,owner);if(!conn)throw new ApiError('Trace is not connected for this team.',404);startTraceBackground(ctx,env,key,owner,{refreshCatalog:b.refresh_catalog!==false,retryErrors:b.retry_errors===true,gameLimit:BACKGROUND_INITIAL_GAMES});return json({ok:true,queued:true,status:await unifiedStatus(env,publicKey,conn,owner)});}
  throw new ApiError('Not found.',404,'not_found');
}


export default {
  async fetch(request,env,ctx){const url=new URL(request.url);if(url.pathname.startsWith('/api/')){try{return await handleApi(request,env,ctx);}catch(e){console.error(e);return json({error:e?.message||'Unexpected server error.',code:e?.code||'server_error'},Number.isInteger(e?.status)?e.status:500);}}if(request.method!=='GET'&&request.method!=='HEAD')return new Response('Method not allowed',{status:405,headers:{Allow:'GET, HEAD'}});const headers={'content-type':'text/html; charset=utf-8','cache-control':'no-store','x-content-type-options':'nosniff','x-frame-options':'DENY','referrer-policy':'no-referrer','permissions-policy':'camera=(), microphone=(), geolocation=()','x-robots-tag':'noindex, nofollow, noarchive','strict-transport-security':'max-age=31536000; includeSubDomains','content-security-policy':"default-src 'self'; script-src 'self' 'unsafe-inline' https://cdn.jsdelivr.net/npm/xlsx@0.18.5/dist/ https://cdn.jsdelivr.net/npm/jspdf@2.5.2/dist/ https://cdn.jsdelivr.net/npm/jspdf-autotable@3.8.4/dist/; style-src 'self' 'unsafe-inline' https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/; font-src 'self' https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/fonts/ data:; img-src 'self' data: blob: https://*.traceup.com; connect-src 'self'; object-src 'none'; base-uri 'none'; frame-ancestors 'none'"};return new Response(request.method==='HEAD'?null:APP_HTML,{headers});},
  async scheduled(_controller,env,ctx){ctx.waitUntil((async()=>{await ensureSchema(env);try{const cfg=await appConfig(env),age=Date.now()-Date.parse(cfg?.last_sync_at||0);if(cfg?.teamsnap_token_enc&&(!Number.isFinite(age)||age>15*60*1000))await syncTeamSnap(env,{full:false});}catch(e){console.error('TeamSnap scheduled sync failed',e);}try{const owner=await installationOwner(env),connections=await env.DB.prepare('SELECT teamsnap_key FROM trace_connections WHERE owner_hash=? ORDER BY COALESCE(last_sync_at,connected_at) ASC LIMIT 3').bind(owner).all();for(const row of connections.results||[])await syncTeam(env,row.teamsnap_key,{owner,gameLimit:BACKGROUND_GAMES_PER_TICK,refreshCatalog:true,retryErrors:false});}catch(e){console.error('Trace scheduled sync failed',e);}await env.DB.prepare('DELETE FROM trace_rate_limits WHERE expires_at<?').bind(Date.now()-TRACE_RATE_WINDOW_MS).run();})());}
};
